    {
        #region Consts
        public const string PERMISSION_ADD = "STA_Vehicle_Add";
        public const string PERMISSION_DELETE = "STA_Vehicle_Delete";
        public const string PERMISSION_EDIT = "STA_Vehicle_Edit";
        public const string PERMISSION_VIEW = "STA_Vehicle_View";

        #endregion

        #region Variables

        DataTable dtbData;
        bool bolIsRefresh = false;

        #endregion

        #region IForm Members

        private static frmSTAVehicle _instance = null;

        public static frmSTAVehicle Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmSTAVehicle();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion


        public frmSTAVehicle()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {
            gvData.OptionsView.NewItemRowPosition = UserSession.HasPermission(PERMISSION_ADD) ? DevExpress.XtraGrid.Views.Grid.NewItemRowPosition.Top : DevExpress.XtraGrid.Views.Grid.NewItemRowPosition.None;
        }

        public void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                ModifyGrid();
            }
        }

        private void ModifyGrid()
        {
            if (gvData.Columns[STA_Vehicle.C_id] == null)
                return;
            if (gvData.Columns[STA_Vehicle.C_id].ColumnEdit == null || bolIsRefresh)
            {
                DevExpress.XtraEditors.Repository.RepositoryItemGridLookUpEdit repository = null;
                if (gvData.Columns[STA_Vehicle.C_id].ColumnEdit != null)
                    repository = gvData.Columns[STA_Vehicle.C_id].ColumnEdit as DevExpress.XtraEditors.Repository.RepositoryItemGridLookUpEdit;

                if (repository == null)
                {
                    repository = new DevExpress.XtraEditors.Repository.RepositoryItemGridLookUpEdit();
                    repository.TextEditStyle = DevExpress.XtraEditors.Controls.TextEditStyles.Standard;
                    repository.PopupFilterMode = DevExpress.XtraEditors.PopupFilterMode.Contains;
                    repository.ImmediatePopup = true;
                }

                TPT_VehicleService.InitRepositoryLookUpEdit(repository);
                gvData.Columns[STA_Vehicle.C_id].ColumnEdit = repository;
            }
        }

        public void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                dtbData = new STA_Vehicle().Search();
                if (dtbData != null)
                {
                    gcData.DataSource = dtbData;
                    SystemService.SYS_GridColumnService.InitGridColumn(gvData, "STA_Vehicle", bolIsRefresh);
                    ModifyGrid();
                    bolIsRefresh = false;
                }
                else
                {
                    ErrorManager.Error("Việc lấy thông tin bị lỗi!");
                }
            }
        }

        /// <summary>
        /// Xóa từng dòng được chọn, bị lỗi chỗ nào thì ngưng chỗ ấy lại
        /// </summary>
        /// <returns></returns>
        private bool DeleteData()
        {
            STA_Vehicle obj = new STA_Vehicle();
            int[] arrRowIndex = gvData.GetSelectedRows();
            for (int i = arrRowIndex.Length - 1; i >= 0; i--)
            {
                DataRow drw = gvData.GetDataRow(arrRowIndex[i]);
                if (drw != null)
                {
                    if (drw.RowState != DataRowState.Added)
                    {
                        if (!obj.Delete(Convert.ToString(drw[STA_Vehicle.C_ten])))
                        {
                            ErrorManager.Error("Dữ liệu đang sử dụng bạn không xóa được!");
                            return false;
                        }
                    }
                    gvData.DeleteRow(arrRowIndex[i]);
                }
            }
            return true;
        }

        /// <summary>
        /// Save dữ liệu ở lưới
        /// </summary>
        private bool SaveData()
        {
            if (dtbData != null)
            {
                STA_Vehicle item0 = new STA_Vehicle();
                item0.BeginTransaction();
                foreach (DataRow drw in dtbData.Rows)
                {
                    if (drw.RowState != DataRowState.Deleted)
                    {
                        STA_Vehicle item = new STA_Vehicle();
                        item.IDB = item0.IDB;
                        if (item.Parse(drw))
                        {
                            if (drw.RowState == DataRowState.Added)
                            {
                                if (!item.Add())
                                {
                                    ErrorManager.Error("Việc thêm thông tin bị lỗi!");
                                    return false;
                                }
                            }
                            else if (drw.RowState == DataRowState.Modified)
                            {
                                if (!item.Update())
                                {
                                    ErrorManager.Error("Việc cập nhật thông tin bị lỗi!");
                                    return false;
                                }
                            }
                        }
                    }
                }
                item0.CommitTransaction();
                return true;
            }
            return true;
        }

        private string CheckValidate(DataRow drw)
        {
            if (drw == null)
                return "";
            STA_Vehicle item = new STA_Vehicle();
            if (item.Parse(drw))
            {
                if (item.Ten == "" || item.Ten == null)
                    return "Bạn phải nhập tên xe trạm!";
            }
            return "";
        }

        /// <summary>
        /// Chọn nhiều dòng -> chuột phải Chọn xe -> gán cùng 1 TPT_Vehicle.VehicleID
        /// </summary>
        private void ApplyVehicleToSelectedRows()
        {
            if (gvData.SelectedRowsCount <= 0)
            {
                MessageManager.Warning("Bạn phải chọn ít nhất một dòng!");
                return;
            }
            if (!UserSession.HasPermission(PERMISSION_EDIT))
            {
                MessageManager.Warning("Bạn không có quyền cập nhật!");
                return;
            }

            Transport.Declaration.frmVehicleSelect frm = Transport.Declaration.frmVehicleSelect.Instance;
            frm.ISMultiSelect = false;
            frm.ShowDialog();
            if (!frm.IsOk || frm.ItemSelected == null || frm.ItemSelected.VehicleID == null)
                return;

            int intVehicleID = Convert.ToInt32(frm.ItemSelected.VehicleID);
            string strVehicleCode = frm.ItemSelected.VehicleCode;
            string strVehicleCode2 = frm.ItemSelected.VehicleCode2;
            string strVehicleName = frm.ItemSelected.VehicleName;

            int[] arrRowIndex = gvData.GetSelectedRows();
            for (int i = 0; i < arrRowIndex.Length; i++)
            {
                DataRow drw = gvData.GetDataRow(arrRowIndex[i]);
                if (drw != null && drw.RowState != DataRowState.Deleted)
                {
                    drw[STA_Vehicle.C_id] = intVehicleID;
                    if (dtbData.Columns.Contains("VehicleCode"))
                        drw["VehicleCode"] = strVehicleCode;
                    if (dtbData.Columns.Contains("VehicleCode2"))
                        drw["VehicleCode2"] = strVehicleCode2;
                    if (dtbData.Columns.Contains("VehicleName"))
                        drw["VehicleName"] = strVehicleName;
                }
            }

            btnSave.Enabled = mnuItemSave.Enabled = true;
            gvData.RefreshData();
            MessageManager.Info(String.Format("Đã gán xe [{0}] cho {1} dòng. Bấm Lưu để cập nhật.", strVehicleName, arrRowIndex.Length));
        }

        private void UpdateSelectVehicleMenu()
        {
            mnuItemSelectVehicle.Enabled = gvData.SelectedRowsCount > 0 && UserSession.HasPermission(PERMISSION_EDIT);
        }

        #endregion

        #region Form Actions

        private void frmSTAVehicle_Load(object sender, EventArgs e)
        {
            new Thread(LoadData).Start();
            new Thread(LoadReferenceData).Start();
            CheckPermission();
            SetToolTip();
            UpdateSelectVehicleMenu();
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private void gvData_SelectionChanged(object sender, DevExpress.Data.SelectionChangedEventArgs e)
        {
            mnuItemDelete.Enabled = btnDelete.Enabled = gvData.SelectedRowsCount > 0 && UserSession.HasPermission(PERMISSION_DELETE);
            UpdateSelectVehicleMenu();
        }

        private void btnDelete_Click(object sender, EventArgs e)
        {
            if (MessageManager.Confirm("Bạn thực sự muốn xóa những dữ liệu này?") == DialogResult.Yes)
            {
                DeleteData();
            }
        }

        private void btnSave_Click(object sender, EventArgs e)
        {
            if (SaveData())
            {
                new Thread(LoadData).Start();
                btnSave.Enabled = mnuItemSave.Enabled = false;
            }
        }

        private void mnuItemRefresh_Click(object sender, EventArgs e)
        {
            bolIsRefresh = true;
            new Thread(LoadData).Start();
            new Thread(LoadReferenceData).Start();
        }

        private void mnuItemExportToExcel_Click(object sender, EventArgs e)
        {
            gvData.QuickExportToExcel();
        }

        private void mnuItemSelectVehicle_Click(object sender, EventArgs e)
        {
            ApplyVehicleToSelectedRows();
        }

        private void frmSTAVehicle_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F1:
                    this.ShowToolTip();
                    break;

                case Keys.F4:
                    if (btnDelete.Enabled)
                        btnDelete_Click(sender, null);
                    break;
                case Keys.F5:
                    mnuItemRefresh_Click(sender, null);
                    break;
                case Keys.F6:
                    if (mnuItemSave.Enabled)
                        btnSave_Click(sender, null);
                    break;
                case Keys.F7:
                    if (mnuItemSelectVehicle.Enabled)
                        mnuItemSelectVehicle_Click(sender, null);
                    break;
                case Keys.F8:
                    gvData.AddNewRow();
                    break;
                case Keys.Escape:
                    break;
            }
        }

        #endregion

        #region Grid Actions

        private void gvData_ShowingEditor(object sender, CancelEventArgs e)
        {
            if (!gvData.IsNewItemRow(gvData.FocusedRowHandle))
            {
                if (!UserSession.HasPermission(PERMISSION_EDIT))
                    e.Cancel = true;
                else
                {
                    switch (gvData.FocusedColumn.FieldName)
                    {
                        case STA_Vehicle.C_ten:
                            e.Cancel = true;
                            break;
                        case "VehicleCode":
                        case "VehicleCode2":
                        case "VehicleName":
                            e.Cancel = true;
                            break;
                    }
                }
            }
        }

        private void gvData_ValidatingEditor(object sender, DevExpress.XtraEditors.Controls.BaseContainerValidateEditorEventArgs e)
        {
            if (gvData.FocusedRowHandle == -999997)
                return;
            string strError = "";
            switch (gvData.FocusedColumn.FieldName)
            {
                case STA_Vehicle.C_ten:
                    e.Valid = Libs.ValidationHelper.ValidateEmptyString(e.Value, "Tên xe trạm không được bỏ trống!", ref strError);
                    if (e.Valid == true)
                    {
                        if (gvData.SearchRow(STA_Vehicle.C_ten, e.Value, gvData.FocusedRowHandle) >= 0)
                        {
                            strError = "Đã tồn tại tên xe trạm này!";
                            e.Valid = false;
                        }
                    }
                    break;
            }

            if (strError != "")
                e.ErrorText = strError;
        }

        private void gvData_ValidateRow(object sender, DevExpress.XtraGrid.Views.Base.ValidateRowEventArgs e)
        {
            string strError = CheckValidate(gvData.GetFocusedDataRow());
            if (strError != "")
            {
                e.ErrorText = strError;
                e.Valid = false;
            }
            else
                btnSave.Enabled = mnuItemSave.Enabled = true;
        }

        private void gvData_InvalidRowException(object sender, DevExpress.XtraGrid.Views.Base.InvalidRowExceptionEventArgs e)
        {
            e.ExceptionMode = DevExpress.XtraEditors.Controls.ExceptionMode.DisplayError;
        }

        private void gvData_CellValueChanged(object sender, DevExpress.XtraGrid.Views.Base.CellValueChangedEventArgs e)
        {
            if (e.Column == null || e.Column.FieldName != STA_Vehicle.C_id)
                return;

            DataRow drw = gvData.GetDataRow(e.RowHandle);
            if (drw == null)
                return;

            if (e.Value == null || Convert.IsDBNull(e.Value))
            {
                if (dtbData.Columns.Contains("VehicleCode"))
                    drw["VehicleCode"] = DBNull.Value;
                if (dtbData.Columns.Contains("VehicleCode2"))
                    drw["VehicleCode2"] = DBNull.Value;
                if (dtbData.Columns.Contains("VehicleName"))
                    drw["VehicleName"] = DBNull.Value;
                return;
            }

            DataRow[] rows = TPT_VehicleService.Table.Select(String.Format("VehicleID = {0}", e.Value));
            if (rows.Length > 0)
            {
                if (dtbData.Columns.Contains("VehicleCode"))
                    drw["VehicleCode"] = rows[0][TPT_Vehicle.C_VehicleCode];
                if (dtbData.Columns.Contains("VehicleCode2"))
                    drw["VehicleCode2"] = rows[0][TPT_Vehicle.C_VehicleCode2];
                if (dtbData.Columns.Contains("VehicleName"))
                    drw["VehicleName"] = rows[0][TPT_Vehicle.C_VehicleName];
            }
        }

        /// <summary>
        /// Dòng đã sửa (Modified) tô màu hồng để dễ nhận biết trước khi Lưu.
        /// </summary>
        private void gvData_RowStyle(object sender, DevExpress.XtraGrid.Views.Grid.RowStyleEventArgs e)
        {
            if (e.RowHandle < 0)
                return;

            DataRow drw = gvData.GetDataRow(e.RowHandle);
            if (drw != null && drw.RowState == DataRowState.Modified)
            {
                e.Appearance.BackColor = Color.LightPink;
                e.HighPriority = true;
            }
        }

        #endregion
    }
}

