function Fix-CrCrLf($path) {
  $bytes = [System.IO.File]::ReadAllBytes($path)
  $list = New-Object System.Collections.Generic.List[byte]
  for ($i = 0; $i -lt $bytes.Length; $i++) {
    # Skip extra CR when pattern is CR CR LF
    if ($bytes[$i] -eq 0x0D -and ($i + 2) -lt $bytes.Length -and $bytes[$i+1] -eq 0x0D -and $bytes[$i+2] -eq 0x0A) {
      continue
    }
    $list.Add($bytes[$i])
  }
  [System.IO.File]::WriteAllBytes($path, $list.ToArray())
  $text = [System.IO.File]::ReadAllText($path)
  $lines = ($text -split "`r`n").Count
  Write-Output "$path -> ~$lines lines, first bytes: $([BitConverter]::ToString(([System.IO.File]::ReadAllBytes($path))[0..40]))"
}
